public voidYaf_Plugin_Abstract::routerStartup Yaf_Request_Abstractrequest Yaf_Response_Abstractresponse
Este gancho é acionado imediatamente antes do roteamento da requisição. É o primeiro gancho do fluxo de despacho, portanto geralmente é usado para reescrita de URLs ou decisões de roteamento que precisam ocorrer antes de Yaf_Router::route ser executado.

  &reftitle.examples;

   Exemplo de Yaf_Plugin_Abstract::routerStartup


<?php
class RewritePlugin extends Yaf_Plugin_Abstract
{
    public function routerStartup(Yaf_Request_Abstract $request, Yaf_Response_Abstract $response)
    {
        /* reescreve URIs no estilo "/about" para "/page/about" antes
         * da execução do roteamento */
        $uri = $request->getRequestUri();
        if (preg_match("#^/[a-z]+$#", $uri)) {
            $request->setRequestUri("/page" . $uri);
        }
    }
}

/* os plugins são registrados no bootstrap */
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initPlugin(Yaf_Dispatcher $dispatcher)
    {
        $dispatcher->registerPlugin(new RewritePlugin());
    }
}
?>
